const $ = s => document.querySelector(s);
const sv = (k, v) => { try { localStorage.setItem(k, v); } catch (e) {} };
const gt = k => { try { return localStorage.getItem(k); } catch (e) { return null; } };
const ic = (n, c = '') => `<span class="ico ${c}" aria-hidden="true">${ICONS[n] || ''}</span>`;
const MAIL = '<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/></svg>';
const IDS = ['about', 'exp', 'projects', 'skills', 'contact'];
let L = gt('lang') || ((navigator.language || 'fr').startsWith('en') ? 'en' : 'fr');
let TH = gt('theme') || (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');

const social = (cls = '') => `<div class="row ${cls}">
  <a class="rb" href="mailto:${CFG.email}" aria-label="E-mail">${MAIL}</a>
  <a class="rb" href="${CFG.github}" target="_blank" rel="noopener noreferrer" aria-label="GitHub">${ic('github')}</a>
  <a class="rb" href="${CFG.linkedin}" target="_blank" rel="noopener noreferrer" aria-label="LinkedIn">${ic('linkedin')}</a></div>`;

function render() {
  const t = T[L];
  document.documentElement.lang = L;
  document.documentElement.dataset.theme = TH;
  document.querySelector('.skip').textContent = t.skip;
  $('#nav').innerHTML = IDS.map((id, i) => `<a href="#${id}">${t.nav[i]}</a>`).join('');
  $('#theme').innerHTML = Object.entries(THEMES).map(([k, v]) => `<option value="${k}"${k === TH ? ' selected' : ''}>${v[L === 'fr' ? 0 : 1]}</option>`).join('');
  $('#lang').textContent = L === 'fr' ? 'EN' : 'FR';
  $('#lang').setAttribute('aria-label', L === 'fr' ? 'Switch to English' : 'Passer en français');
  $('#main').innerHTML = `
  <div class="w"><div class="hero" id="hero">
    <div class="rv"><p class="lab">${t.kicker}</p><h1>Douae Aterbi</h1><p class="lead">${t.lead}</p>
      <span class="badge">${t.badge}</span>
      <div class="row"><a class="btn p" href="#projects">${t.b1}</a><a class="btn" href="#contact">${t.b2}</a></div>
      ${social()}</div>
    <img class="ph rv" src="assets/photo.jpg" alt="Douae Aterbi" width="280" height="280"></div></div>
  <section id="about"><div class="w rv"><p class="lab">01</p><h2>${t.h.about}</h2><div class="about">${t.about.map(p => `<p>${p}</p>`).join('')}</div></div></section>
  <section id="exp"><div class="w rv"><p class="lab">02</p><h2>${t.h.exp}</h2><div class="tl">${t.exp.map(e => `<div class="it"><h3>${e.r}</h3><p class="meta">${e.o} · ${e.d}</p><p class="pj">${e.p}</p><ul>${e.b.map(b => `<li>${b}</li>`).join('')}</ul></div>`).join('')}</div></div></section>
  <section id="projects"><div class="w"><div class="rv"><p class="lab">03</p><h2>${t.h.projects}</h2></div><div class="grid">${Object.entries(t.pj).map(([k, p]) => {
    const l = LINKS[k] || {};
    const a = (u, n) => u ? `<a class="btn" href="${u}" target="_blank" rel="noopener noreferrer">${n}</a>` : '';
    return `<article class="card rv"><h3>${p[0]}</h3><p class="meta">${p[1]}</p><p>${p[2]}</p><div class="tags">${p[3].map(s => `<span>${s}</span>`).join('')}</div>${l.repo || l.demo ? `<div class="row" style="margin-top:6px">${a(l.repo, t.repo)}${a(l.demo, t.demo)}</div>` : ''}</article>`;
  }).join('')}</div></div></section>
  <section id="skills"><div class="w"><div class="rv"><p class="lab">04</p><h2>${t.h.skills}</h2></div>
    ${SK.map(([g, list]) => `<div class="grp rv"><h3>${t.grp[g]}</h3><div class="tiles">${list.map(([n, i]) => `<div class="tile">${ic(i)}<span>${n}</span></div>`).join('')}</div></div>`).join('')}
    <div class="grp rv"><div class="chips">${t.meth.map(m => `<span>${m}</span>`).join('')}</div></div>
    <div class="rv" style="margin-top:44px"><h2 style="font-size:24px;margin-bottom:16px">${t.h.cert}</h2><ul class="cert">${t.cert.map(c => `<li>${c[0]}<small>${c[1]}</small></li>`).join('')}</ul></div></div></section>
  <section id="contact"><div class="w ct">
    <div class="rv"><p class="lab">05</p><h2>${t.ctTitle}</h2><p class="about">${t.ctText}</p>${social()}</div>
    <form class="rv" id="cf" novalidate>
      <label>${t.f.name}<input name="name" autocomplete="name" required></label>
      <label>${t.f.email}<input name="email" type="email" autocomplete="email" required></label>
      <label>${t.f.msg}<textarea name="message" required></textarea></label>
      <input class="hp" name="website" tabindex="-1" autocomplete="off" aria-hidden="true">
      <div class="row" style="margin:0"><button class="btn p" type="submit">${t.f.send}</button><span id="fs" role="status"></span></div>
    </form></div></section>`;
  $('#foot').textContent = t.foot;
  $('#cf').addEventListener('submit', send);
  const io = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); } }), { threshold: .08 });
  document.querySelectorAll('.rv').forEach(el => io.observe(el));
}

async function send(e) {
  e.preventDefault();
  const t = T[L].f, f = e.target, d = Object.fromEntries(new FormData(f)), st = $('#fs');
  if (d.website) return;
  if (!f.checkValidity()) { f.reportValidity(); return; }
  if (!CFG.web3formsKey && !CFG.formEndpoint) {
    location.href = `mailto:${CFG.email}?subject=${encodeURIComponent(t.sub + ' ' + d.name)}&body=${encodeURIComponent(d.message + '\n\n' + d.email)}`;
    return;
  }
  try {
    const body = { name: d.name, email: d.email, message: d.message, subject: t.sub + ' ' + d.name };
    if (CFG.web3formsKey) body.access_key = CFG.web3formsKey;
    const r = await fetch(CFG.web3formsKey ? 'https://api.web3forms.com/submit' : CFG.formEndpoint, { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json' }, body: JSON.stringify(body) });
    if (!r.ok) throw new Error('http');
    f.reset(); st.textContent = t.ok;
  } catch (err) { st.textContent = t.ko; }
}

$('#theme').addEventListener('change', e => { TH = e.target.value; sv('theme', TH); document.documentElement.dataset.theme = TH; });
$('#lang').addEventListener('click', () => { L = L === 'fr' ? 'en' : 'fr'; sv('lang', L); render(); });
$('#menu').addEventListener('click', () => { const o = $('#nav').classList.toggle('open'); $('#menu').setAttribute('aria-expanded', o); });
$('#nav').addEventListener('click', () => { $('#nav').classList.remove('open'); $('#menu').setAttribute('aria-expanded', false); });
render();
